import{_ as a,C as l,o as i,c as u,j as r,a as o,E as n,a2 as s}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse('{"title":"Atome et éditeur","description":"","frontmatter":{"title":"Atome et éditeur"},"headers":[],"relativePath":"guide/atom.md","filePath":"guide/atom.md"}'),g={name:"guide/atom.md"};function d(c,e,p,m,h,b){const t=l("Capture");return i(),u("div",null,[e[0]||(e[0]=r("h1",{id:"atome-et-editeur",tabindex:"-1"},[o("Atome et éditeur "),r("a",{class:"header-anchor",href:"#atome-et-editeur","aria-label":'Permalink to "Atome et éditeur"'},"​")],-1)),e[1]||(e[1]=r("p",null,[o("Un "),r("strong",null,"atome"),o(" est une note de votre mémoire : un fichier Markdown. Cet écran la montre en lecture et, d'un clic sur "),r("strong",null,"Éditer"),o(", la rend modifiable dans une seule surface de texte.")],-1)),n(t,{name:"atome-lecture",alt:"Une note en lecture : plan, propriétés et liens entrants à droite, encadré d'avertissement et tableau dans le texte."}),e[2]||(e[2]=s('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>La barre d&#39;outils</strong> : <strong>Éditer</strong> (qui devient <strong>Lire</strong> en édition), <strong>Renommer</strong>, <strong>Déplacer</strong>, <strong>Retirer</strong> et <strong>Exporter…</strong>.</li><li><strong>L&#39;en-tête</strong> : le titre de la note, puis une ligne grise avec sa zone, son chemin, sa taille et sa date (« modifié 02.10.2026 · 12:00 »). Les étiquettes de la note s&#39;affichent en pastilles sous cette ligne.</li><li><strong>Le texte</strong> : titres, listes, tableaux, encadrés, images, tel que le fichier le décrit.</li><li><strong>La colonne de droite</strong> : <ul><li><strong>PLAN</strong> : les titres de la note. Il n&#39;apparaît qu&#39;à partir de deux titres, et il disparaît en édition : l&#39;éditeur a son propre plan, qui s&#39;ouvre avec <strong>⌘⇧O</strong>.</li><li><strong>PROPRIÉTÉS DE LA NOTE</strong> : les champs de l&#39;en-tête du fichier (type, status, date…). <strong>Voir l&#39;autre propriété</strong> ou <strong>Voir les N autres propriétés</strong> déplie le reste, <strong>Réduire aux propriétés principales</strong> le replie.</li><li><strong>LIENS ENTRANTS</strong> : les notes qui citent celle-ci, avec leur date. Si aucune ne la cite, la colonne le dit : « Aucune note ne s’appuie sur celle-ci ».</li></ul></li><li><strong>En édition</strong>, trois éléments s&#39;ajoutent (voir plus bas) : la marge qui nomme chaque bloc, un panneau <strong>MÉMOIRE</strong> dans la colonne de droite, et une barre d&#39;état en bas du texte : <strong>Ligne 7 · Markdown · UTF-8 · Enregistré</strong>, puis <strong>Annuler</strong> et <strong>Enregistrer</strong>.</li></ul><p>Dans une fenêtre étroite, la colonne de droite passe sous le texte. Le bouton <strong>Replier les propriétés, le plan et les liens</strong> (ou <strong>Afficher les propriétés, le plan et les liens</strong>) la ferme ou la rouvre.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="lire-une-note" tabindex="-1">Lire une note <a class="header-anchor" href="#lire-une-note" aria-label="Permalink to &quot;Lire une note&quot;">​</a></h3><p>Faites défiler le texte. Dans la colonne de droite, un clic sur un titre du <strong>PLAN</strong> vous y amène, et un clic sur une ligne de <strong>LIENS ENTRANTS</strong> ouvre la note qui vous cite.</p><ul><li>Un lien vers une autre note (<code>[[…]]</code>) est cliquable et ouvre cette note dans un onglet.</li><li>Un lien dont la cible n&#39;existe pas reste affiché, mais ne mène nulle part. Passez la souris dessus : « Aucune note nommée … — ce lien est à réparer ».</li><li>Un lien vers une adresse web n&#39;est pas cliquable. L&#39;adresse s&#39;affiche quand vous passez la souris dessus.</li><li>Une case d&#39;une liste de tâches se coche d&#39;un clic, même en lecture : le fichier est mis à jour. Si l&#39;écriture échoue, un message vous le dit et vous invite à rouvrir la note.</li></ul><h3 id="editer-une-note" tabindex="-1">Éditer une note <a class="header-anchor" href="#editer-une-note" aria-label="Permalink to &quot;Éditer une note&quot;">​</a></h3><p>Cliquez sur <strong>Éditer</strong>. Le texte devient une <strong>surface unique de Markdown</strong> : vous écrivez directement dedans, comme dans une page.</p>',9)),n(t,{name:"atome-edition",alt:"La note en édition : la marge nomme chaque bloc (H1, ¶, H2, puces, encadré) et, au survol d'un bloc, la poignée « + » et la prise de déplacement apparaissent."}),e[3]||(e[3]=s('<p>Hors de la ligne où se trouve votre curseur, vous voyez le rendu : titres en grand, gras en gras. Sur la ligne du curseur, la syntaxe apparaît (<code>#</code>, <code>**</code>, <code>[[…]]</code>) pour que vous puissiez la modifier. Dès que vous changez de ligne, elle se referme.</p><p>Le fichier reste du Markdown ordinaire : rien n&#39;y est ajouté par l&#39;éditeur.</p><h3 id="enregistrer-ou-annuler" tabindex="-1">Enregistrer ou annuler <a class="header-anchor" href="#enregistrer-ou-annuler" aria-label="Permalink to &quot;Enregistrer ou annuler&quot;">​</a></h3><p>La barre d&#39;état en bas du texte dit où vous en êtes : <strong>Enregistré</strong>, ou <strong>Modifié</strong> quand il y a du texte non enregistré. Un point apparaît aussi sur l&#39;onglet de la note.</p><ul><li><strong>Enregistrer</strong> écrit le fichier. Le bouton reste grisé tant que rien n&#39;a changé. L&#39;éditeur reste ouvert après l&#39;enregistrement, et votre historique d&#39;annulation est conservé.</li><li><strong>Annuler</strong> referme l&#39;éditeur et revient à la lecture, sans enregistrer.</li><li><strong>⌘Z</strong> annule le dernier geste, <strong>⌘⇧Z</strong> le rétablit.</li><li>Si l&#39;éditeur refuse d&#39;écrire (le texte ne correspondrait plus à ce qu&#39;il a lu), un message l&#39;indique et rien n&#39;est écrit.</li></ul><p>Un onglet qui porte des modifications non enregistrées refuse de se fermer : enregistrez ou annulez d&#39;abord. Quitter Kessho avec du texte non enregistré demande confirmation ; cette question se désactive dans <a href="/Kessho/guide/settings.html">Réglages</a> &gt; <strong>Apparence</strong>.</p><h3 id="lire-la-marge" tabindex="-1">Lire la marge <a class="header-anchor" href="#lire-la-marge" aria-label="Permalink to &quot;Lire la marge&quot;">​</a></h3><p>À gauche du texte, la marge nomme chaque bloc par un signe : <strong>H1</strong> à <strong>H6</strong> pour les titres, <strong>¶</strong> pour un paragraphe, <strong>•</strong> pour une liste à puces, <strong>1.</strong> pour une liste numérotée, <strong>☐</strong> pour une liste de tâches, <strong>❝</strong> pour une citation, <strong>!</strong> pour un encadré, <strong>&lt;/&gt;</strong> pour du code, <strong>▦</strong> pour un tableau, <strong>▣</strong> pour une image, <strong>⧉</strong> pour une inclusion, <strong>—</strong> pour une règle. Une liste ne porte qu&#39;un signe, sur sa première ligne.</p><p>La marge ne fait que s&#39;afficher : elle n&#39;écrit rien dans le fichier. Quand la fenêtre est trop étroite, elle se replie.</p><h3 id="deplacer-dupliquer-ou-supprimer-un-bloc" tabindex="-1">Déplacer, dupliquer ou supprimer un bloc <a class="header-anchor" href="#deplacer-dupliquer-ou-supprimer-un-bloc" aria-label="Permalink to &quot;Déplacer, dupliquer ou supprimer un bloc&quot;">​</a></h3><p>Passez la souris sur un bloc : deux boutons apparaissent dans la marge, un <strong>+</strong> et une prise à six points.</p>',11)),n(t,{name:"menu-bloc",alt:"Le menu du bloc, ouvert en cliquant la poignée : transformer, dupliquer, monter, descendre, supprimer."}),e[4]||(e[4]=s("<ul><li><strong>Glissez la prise</strong> pour déplacer le bloc. Maintenez <strong>⌥</strong> pour le copier au lieu de le déplacer. <strong>Échap</strong> annule le glissement.</li><li><strong>Cliquez la prise</strong> (sans bouger) : le bloc est sélectionné et son menu s&#39;ouvre. <ul><li><strong>Transformer en…</strong> ouvre le menu <code>/</code> pour changer le type du bloc.</li><li><strong>Dupliquer</strong> (⌘D) copie le bloc juste dessous.</li><li><strong>Monter</strong> (⌘⌥↑) et <strong>Descendre</strong> (⌘⌥↓) le font avancer d&#39;un cran. <strong>Monter</strong> est grisé sur le premier bloc.</li><li><strong>Supprimer</strong> (⌫) l&#39;efface.</li></ul></li></ul><p>Une liste se déplace, se duplique et se supprime d&#39;un seul bloc : on ne la coupe pas en deux.</p>",2)),n(t,{name:"glisser-bloc",alt:"Un bloc glissé par sa poignée : le bandeau « Déplacement » nomme la destination et la ligne d'insertion se place avant « Choix des rails »."}),e[5]||(e[5]=s('<h3 id="ajouter-un-bloc-avec-le" tabindex="-1">Ajouter un bloc avec le + <a class="header-anchor" href="#ajouter-un-bloc-avec-le" aria-label="Permalink to &quot;Ajouter un bloc avec le +&quot;">​</a></h3><p>Le <strong>+</strong> de la marge (« Ajouter un bloc dessous ») crée un paragraphe vide sous le bloc survolé et ouvre aussitôt le menu <code>/</code> dessus.</p><h3 id="choisir-le-type-d-un-bloc-avec-le-menu" tabindex="-1">Choisir le type d&#39;un bloc avec le menu / <a class="header-anchor" href="#choisir-le-type-d-un-bloc-avec-le-menu" aria-label="Permalink to &quot;Choisir le type d&#39;un bloc avec le menu /&quot;">​</a></h3><p>Tapez <code>/</code> en tout début de ligne. Le menu <strong>Commandes de bloc</strong> s&#39;ouvre.</p>',4)),n(t,{name:"menu-slash",alt:"Le menu « / » ouvert sur un nouveau paragraphe : paragraphe, titres, listes, citation, code, tableau, encadré, règle."}),e[6]||(e[6]=s('<p>Il propose : <strong>Paragraphe</strong>, <strong>Titre de niveau 1</strong> à <strong>6</strong>, <strong>Liste</strong>, <strong>Liste numérotée</strong>, <strong>Liste de tâches</strong>, <strong>Citation</strong>, <strong>Code</strong>, <strong>Tableau</strong>, <strong>Encadré</strong>, <strong>Bloc repliable</strong> et <strong>Règle horizontale</strong>.</p><ul><li>Continuez à taper pour filtrer : <code>/tab</code> ne garde que <strong>Tableau</strong>.</li><li><strong>↑</strong> et <strong>↓</strong> parcourent la liste, <strong>Entrée</strong> ou <strong>Tab</strong> choisit, <strong>Échap</strong> ferme.</li><li>Un <code>/</code> au milieu d&#39;un texte (une date, un chemin) n&#39;ouvre rien.</li></ul><h3 id="mettre-en-forme-du-texte" tabindex="-1">Mettre en forme du texte <a class="header-anchor" href="#mettre-en-forme-du-texte" aria-label="Permalink to &quot;Mettre en forme du texte&quot;">​</a></h3><p>Sélectionnez des mots : la barre <strong>Mise en forme</strong> apparaît au-dessus de la sélection. Elle a cinq boutons : <strong>Gras</strong> (B), <strong>Italique</strong> (I), <strong>Barré</strong> (S), <strong>Surligné</strong> (H) et <strong>Code en ligne</strong> (&lt;/&gt;). Un second clic sur un bouton déjà actif retire la mise en forme.</p>',4)),n(t,{name:"barre-de-format",alt:"Une phrase sélectionnée dans l'éditeur : la barre de mise en forme (gras, italique, barré, surlignage, code) apparaît juste au-dessus."}),e[7]||(e[7]=r("p",null,"Les mêmes gestes ont des raccourcis (liste plus bas). Un clic dans la barre ne perd pas votre sélection.",-1)),e[8]||(e[8]=r("h3",{id:"travailler-dans-un-tableau",tabindex:"-1"},[o("Travailler dans un tableau "),r("a",{class:"header-anchor",href:"#travailler-dans-un-tableau","aria-label":'Permalink to "Travailler dans un tableau"'},"​")],-1)),e[9]||(e[9]=r("p",null,"Un tableau s'écrit en Markdown, mais se manie à la souris et au clavier.",-1)),n(t,{name:"menu-cellule",alt:"Le menu « / » dans une cellule de tableau : insérer ou supprimer une ligne ou une colonne, aligner la colonne."}),e[10]||(e[10]=s('<ul><li><strong>Menu <code>/</code> dans une cellule</strong> : tapez <code>/</code> au début d&#39;une cellule. Dans le corps du tableau, le menu propose neuf entrées : <strong>Insérer une ligne au-dessus</strong>, <strong>Insérer une ligne en dessous</strong>, <strong>Supprimer la ligne</strong>, <strong>Insérer une colonne à gauche</strong>, <strong>Insérer une colonne à droite</strong>, <strong>Supprimer la colonne</strong>, puis <strong>Aligner à gauche</strong>, <strong>Aligner au centre</strong> et <strong>Aligner à droite</strong>. Dans la ligne d&#39;en-tête, il n&#39;en propose que sept : <strong>Insérer une ligne au-dessus</strong> et <strong>Supprimer la ligne</strong> n&#39;y sont pas. <strong>Supprimer la colonne</strong> n&#39;est pas proposé quand le tableau n&#39;a qu&#39;une colonne.</li><li><strong>Tab</strong> passe à la cellule suivante, <strong>⇧Tab</strong> à la précédente. <strong>Tab</strong> dans la dernière cellule ajoute une ligne.</li><li><strong>⌘↵</strong> ajoute une ligne dessous. <strong>⌥Tab</strong> ajoute une colonne.</li><li><strong>⌘⌥⏎</strong> ajoute une ligne, <strong>⌘⌥⇧⏎</strong> une colonne, <strong>⌘⌥⌫</strong> retire la ligne, <strong>⌘⌥⇧⌫</strong> retire la colonne.</li></ul><p>Si le tableau n&#39;a pas de ligne de séparation valide, l&#39;éditeur vous demande de le corriger à la main avant d&#39;utiliser ces gestes.</p><h3 id="poser-un-encadre" tabindex="-1">Poser un encadré <a class="header-anchor" href="#poser-un-encadre" aria-label="Permalink to &quot;Poser un encadré&quot;">​</a></h3><p>Choisissez <strong>Encadré</strong> (ou <strong>Bloc repliable</strong>) dans le menu <code>/</code>. Un encadré est une citation Markdown dont la première ligne est <code>&gt; [!type]</code>.</p>',4)),n(t,{name:"encadre-type",alt:"Le menu de type d'un encadré, ouvert depuis sa tête : note, astuce, attention, danger, citation, avec les options de repli."}),e[11]||(e[11]=s('<ul><li>Mettez le curseur sur la ligne d&#39;en-tête : le mot du type (<code>note</code>, <code>warning</code>…) devient un bouton. Cliquez-le, ou tapez <strong>⌥↵</strong>, pour ouvrir le menu <strong>Type de l&#39;encadré</strong> : <strong>Note</strong>, <strong>Astuce</strong>, <strong>Attention</strong>, <strong>Danger</strong>, <strong>Citation</strong>.</li><li>Dans le même menu, <strong>Replié par défaut</strong> et <strong>Non repliable</strong> règlent le repli. Un encadré repliable porte un chevron (<strong>Replier</strong> / <strong>Déplier</strong>).</li></ul><h3 id="ajouter-une-image" tabindex="-1">Ajouter une image <a class="header-anchor" href="#ajouter-une-image" aria-label="Permalink to &quot;Ajouter une image&quot;">​</a></h3><p>Collez une image ou glissez un fichier image dans le texte. Les formats admis sont png, jpg, gif et webp, jusqu&#39;à 10 Mo ; au-delà, l&#39;image n&#39;est pas ajoutée et un message vous le dit. L&#39;image est rangée avec votre mémoire et un lien est écrit dans la note.</p><ul><li>Tirez les poignées sur les côtés de l&#39;image pour changer sa largeur.</li><li><strong>Ajouter une légende</strong> : le champ sous l&#39;image. La légende devient le texte alternatif de l&#39;image.</li><li>Sélectionnez l&#39;image puis tapez <strong>⌫</strong> : elle quitte le texte, le fichier reste dans la mémoire.</li></ul><h3 id="relier-vos-notes" tabindex="-1">Relier vos notes <a class="header-anchor" href="#relier-vos-notes" aria-label="Permalink to &quot;Relier vos notes&quot;">​</a></h3><ul><li>Tapez <code>[[</code> : une liste de notes propose des cibles (huit au plus). Tapez <code>#</code> pour proposer des étiquettes. <strong>↑</strong> <strong>↓</strong> parcourent, <strong>Entrée</strong> ou <strong>Tab</strong> choisit.</li><li><strong>⌘K</strong> ouvre la fenêtre <strong>Lien</strong> : <strong>Texte affiché</strong>, puis <strong>Destination : note de la mémoire ou adresse web</strong>. Elle montre ce qui sera écrit dans le fichier (« Sera écrit dans le fichier »). <strong>Insérer</strong> valide.</li><li><strong>⌘ + clic</strong> sur un lien <code>[[…]]</code> ouvre la note visée.</li><li>Dans le panneau <strong>MÉMOIRE</strong> de la colonne de droite, <strong>Filtrer les notes</strong> cherche une note. Glissez-la dans le texte : un choix s&#39;affiche au point de dépôt, <strong>Lien</strong> (touche 1) ou <strong>Inclusion, contenu affiché</strong> (touche 2). <strong>Échap</strong> annule.</li></ul>',6)),n(t,{name:"lien",alt:"La fenêtre de lien sur un texte sélectionné : la destination « Mat » propose la note « Matériel d'éclairage » et montre ce qui sera écrit dans le fichier."}),e[12]||(e[12]=r("h3",{id:"selectionner-et-deplacer-des-paragraphes",tabindex:"-1"},[o("Sélectionner et déplacer des paragraphes "),r("a",{class:"header-anchor",href:"#selectionner-et-deplacer-des-paragraphes","aria-label":'Permalink to "Sélectionner et déplacer des paragraphes"'},"​")],-1)),e[13]||(e[13]=r("p",null,[r("strong",null,"Échap"),o(" dans le texte sélectionne le bloc du curseur. La barre au-dessus de la barre d'état dit alors : « N paragraphes · ⌥↑↓ déplacer · / transformer · ⌫ suppr. ».")],-1)),n(t,{name:"selection-blocs",alt:"Après Échap, la sélection s'arrondit à des blocs entiers : les paragraphes touchés sont surlignés et la barre du bas annonce « 3 paragraphes » avec leurs gestes."}),e[14]||(e[14]=s('<ul><li><strong>⇧↑</strong> et <strong>⇧↓</strong> étendent la sélection.</li><li><strong>⌥↑</strong> et <strong>⌥↓</strong> déplacent les paragraphes sélectionnés.</li><li><strong>/</strong> les transforme, <strong>⌫</strong> les supprime, <strong>⌘C</strong> et <strong>⌘X</strong> les copient ou les coupent.</li></ul><h3 id="rechercher-et-remplacer" tabindex="-1">Rechercher et remplacer <a class="header-anchor" href="#rechercher-et-remplacer" aria-label="Permalink to &quot;Rechercher et remplacer&quot;">​</a></h3><p><kbd>⌘F</kbd> ouvre la fenêtre <strong>Rechercher et remplacer</strong>, <kbd>⌘⌥F</kbd> l&#39;ouvre sur l&#39;onglet de remplacement. Elle a trois onglets : <strong>Rechercher</strong>, <strong>Remplacer</strong> et <strong>Dans la mémoire</strong>, qui cherche dans toutes vos notes et liste celles qui contiennent le texte.</p>',3)),n(t,{name:"recherche-remplacer",alt:"La fenêtre Rechercher et remplacer, onglet Remplacer : « rail » est saisi, les six occurrences sont repérées dans la note et le texte de remplacement est prêt."}),e[15]||(e[15]=s('<ul><li>Les options : <strong>Respecter la casse</strong>, <strong>Mot entier</strong>, <strong>Expression régulière</strong> (<strong>Expression invalide</strong> si elle ne s&#39;écrit pas correctement) et <strong>Boucler en fin</strong>.</li><li>La <strong>Portée</strong> se règle sur <strong>Note</strong> ou <strong>Sélection</strong>.</li><li>Le compteur dit « 2 sur 4 » ; <strong>Précédent</strong> et <strong>Suivant</strong> parcourent les occurrences.</li><li><strong>Remplacer</strong> change l&#39;occurrence courante, <strong>Tout remplacer</strong> les change toutes. <strong>⌘Z</strong> annule <strong>Tout remplacer</strong> en une seule fois.</li><li>Si le texte sélectionné tient sur une ligne, il remplit le champ de recherche.</li></ul><h3 id="voir-le-plan" tabindex="-1">Voir le plan <a class="header-anchor" href="#voir-le-plan" aria-label="Permalink to &quot;Voir le plan&quot;">​</a></h3><p><strong>⌘⇧O</strong> affiche ou masque le <strong>Plan</strong> de la note dans la colonne de droite. Cliquez un titre pour y aller. Glissez un titre dans le plan : toute sa section se déplace avec lui.</p>',3)),n(t,{name:"plan",alt:"Le plan de la note, ouvert en haut du panneau de droite : titre et sections, pour se déplacer d'un coup dans le texte."}),e[16]||(e[16]=r("h3",{id:"exporter-ou-imprimer",tabindex:"-1"},[o("Exporter ou imprimer "),r("a",{class:"header-anchor",href:"#exporter-ou-imprimer","aria-label":'Permalink to "Exporter ou imprimer"'},"​")],-1)),e[17]||(e[17]=r("p",null,[r("strong",null,"Exporter…"),o(" (barre d'outils) ou "),r("strong",null,"⌘⇧E"),o(" ouvre la fenêtre "),r("strong",null,"Exporter la note"),o(", avec un aperçu. Pour le HTML, il suit vos réglages ; pour le PDF, il ne tient compte que de la page et des marges, pas du thème ni des éléments inclus.")],-1)),n(t,{name:"export",alt:"La fenêtre d'export d'une note : format, page, marges, thème et contenu à inclure, avec l'aperçu de la page à gauche."}),e[18]||(e[18]=s('<ul><li><strong>Format</strong> : <strong>HTML (fichier autonome)</strong> ou <strong>PDF (impression du système)</strong>.</li><li><strong>Page</strong> : <strong>A4</strong> ou <strong>Lettre US</strong>. <strong>Marges</strong> : <strong>Étroites</strong>, <strong>Normales</strong> ou <strong>Larges</strong>. <strong>Thème</strong> : <strong>Clair</strong>, <strong>Sombre</strong> ou <strong>Suivre le système</strong>.</li><li><strong>Inclure</strong> : <strong>Titre de la note</strong>, <strong>Table des matières</strong>, <strong>Propriétés (frontmatter)</strong>, <strong>Encadrés repliés ouverts</strong>.</li><li><strong>Destination</strong> (HTML) : <strong>Téléchargements</strong>, <strong>Documents</strong> ou <strong>Bureau</strong>. Pour le PDF, le bouton devient <strong>Imprimer…</strong> et la fenêtre d&#39;impression du système demande le nom et la destination.</li><li>Vos réglages sont retenus note par note, sur cet ordinateur.</li></ul><p><strong>⌘P</strong> imprime directement la note pendant l&#39;édition.</p><h3 id="les-raccourcis-et-les-changer" tabindex="-1">Les raccourcis, et les changer <a class="header-anchor" href="#les-raccourcis-et-les-changer" aria-label="Permalink to &quot;Les raccourcis, et les changer&quot;">​</a></h3><p>Voici les touches par défaut sur Mac. Sous Windows, <strong>⌘</strong> devient <strong>Ctrl</strong> et <strong>⌥</strong> devient <strong>Alt</strong>.</p><table tabindex="0"><thead><tr><th>Geste</th><th>Touches</th></tr></thead><tbody><tr><td>Annuler / Rétablir</td><td>⌘Z / ⌘⇧Z (ou ⌃Y)</td></tr><tr><td>Gras, Italique</td><td>⌘B, ⌘I</td></tr><tr><td>Barré, Surligné</td><td>⌘⇧S, ⌘⇧H</td></tr><tr><td>Code en ligne</td><td>⌘E</td></tr><tr><td>Titre 1 à 6, Paragraphe</td><td>⌘⌥1 à ⌘⌥6, ⌘⌥0</td></tr><tr><td>Liste numérotée, Liste à puces, Liste de tâches</td><td>⌘⇧7, ⌘⇧8, ⌘⇧9</td></tr><tr><td>Citation, Bloc de code</td><td>⌘⌥Q, ⌘⌥C</td></tr><tr><td>Monter, Descendre, Dupliquer le bloc</td><td>⌘⌥↑, ⌘⌥↓, ⌘D</td></tr><tr><td>Insérer un lien</td><td>⌘K</td></tr><tr><td>Rechercher, Remplacer</td><td>⌘F, ⌘⌥F</td></tr><tr><td>Plan, Exporter, Imprimer</td><td>⌘⇧O, ⌘⇧E, ⌘P</td></tr><tr><td>Ajouter une ligne, une colonne au tableau</td><td>⌘⌥⏎, ⌘⌥⇧⏎</td></tr><tr><td>Retirer la ligne, la colonne du tableau</td><td>⌘⌥⌫, ⌘⌥⇧⌫</td></tr></tbody></table><p>Ces raccourcis ne marchent que dans l&#39;éditeur. Pour en changer un, ouvrez <a href="/Kessho/guide/settings.html">Réglages</a> &gt; <strong>Raccourcis</strong>, section <strong>Dans l&#39;éditeur</strong> : cliquez <strong>Modifier</strong> en face du geste, puis tapez la combinaison voulue. <strong>Échap</strong> annule. Une combinaison sans <strong>⌘</strong> (ou <strong>Ctrl</strong>), réservée au système ou déjà prise par un autre geste est refusée, avec la raison. <strong>Rétablir</strong> remet la touche d&#39;origine, <strong>Tout rétablir</strong> remet toutes les touches.</p>',6))])}const q=a(g,[["render",d]]);export{f as __pageData,q as default};
